from solution import three_color

def test_1():
    c = three_color(3, [(0, 1), (1, 2), (0, 2)])
    assert len(c) == 3 and set(c) <= {0, 1, 2}
    assert all(c[u] != c[v] for u, v in [(0, 1), (1, 2), (0, 2)])

def test_2():
    E = [(0, 1), (0, 2), (0, 3), (1, 2), (1, 3), (2, 3)]
    c = three_color(4, E)
    assert len(c) == 4 and set(c) <= {0, 1, 2}
    assert all(c[u] != c[v] for u, v in E)


